commands.command:
url='%s'
path=${url#https://open.spotify.com/}
type=${path%%/*}
id=${path#*/}
id=${id%%\?*}

xdg-open "spotify:$type:$id"

url="$(curl -Ls '%s' | \
  xmllint --html --xpath 'string(//a[img[@alt="Spotify"]]/@href)' -
)"
path=${url#https://open.spotify.com/}
type=${path%%/*}
id=${path#*/}
id=${id%%\?*}

xdg-open "spotify:$type:$id"
